        private static string TranslateSmbFailure(string value)
        {
            const string prefix = "Die echte SMB-Verbindung scheitert bei ";
            if (!value.StartsWith(prefix, StringComparison.Ordinal)) return null;
            int split = value.IndexOf(": ", prefix.Length, StringComparison.Ordinal);
            if (split < 0) return null;
            string stage = value.Substring(prefix.Length, split - prefix.Length);
            switch (stage)
            {
                case "Input": stage = "Eingabeprüfung"; break;
                case "Connect": stage = "TCP-Verbindung"; break;
                case "Negotiate": stage = "SMB-Aushandlung"; break;
                case "Login": stage = "SMB-Anmeldung"; break;
                case "TreeConnect": stage = "Freigabe verbinden"; break;
                case "OpenDirectory": stage = "Ordner öffnen"; break;
                case "ListDirectory": stage = "Ordner auflisten"; break;
            }
            return Format("Die echte SMB-Verbindung scheitert bei {0}: {1}", T(stage), TranslateDiagnostic(value.Substring(split + 2)));
        }

        private static void RunSmbVerificationSelfTest()
        {
            string saved = Language;
            try
            {
                foreach (LanguageItem item in Languages)
                {
                    Language = item.Code;
                    string login = @"HOME-PC\VisitorAccount";
                    string detail = Format("Die SMB-Anmeldung mit {0}, der Zugriff auf die Freigabe und das Auflisten des Ordners funktionieren. Geprüft wurde eine echte SMB-Verbindung von diesem PC.", login);
                    if (!detail.Contains(login)) throw new InvalidOperationException("SMB localization changed an account name.");
                    string message = "Die echte SMB-Verbindung scheitert bei Login: Der SMB-Server verweigert diesen Zugriff (STATUS_ACCESS_DENIED).";
                    WorkerResult result = TranslateResult(new WorkerResult { LoginUserName = login, Message = message, Checks = new[] { new CheckItem { Name = "SMB-Verbindung", State = "error", Code = "SMB_CONNECTION_FAILED", Detail = message } } });
                    if (result.LoginUserName != login || result.Checks[0].Code != "SMB_CONNECTION_FAILED" || !result.Message.Contains("STATUS_ACCESS_DENIED") || result.Message.Contains("bei Login:")) throw new InvalidOperationException("SMB localization lost status data or the translated stage.");
                    if (result.Checks[0].Detail != result.Message) throw new InvalidOperationException("SMB details were translated inconsistently.");
                    if (item.Code != "de" && (result.Message.Contains("Der SMB-Server verweigert") || T("SMB-Verbindung noch offen") == "SMB-Verbindung noch offen")) throw new InvalidOperationException("SMB verification instructions are not translated.");
                }
            }
            finally { Language = saved; }
        }
    }
